tasks.check:
set -o pipefail
cd /home/bcorfman/dev/freytag-forge
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
D=data/stories/continuity-initiative
CH=$(git status --porcelain | awk '{print $NF}')
for f in $CH; do case "$f" in storygame/*|packages/*|tests/fixtures/stories/lighthouse-incident/*|tests/test_lighthouse_ending.py) ;; esac; done
git diff --quiet -- $D/plot.md HEAD 2>/dev/null; true
for f in $D/incidents.yaml $D/pacing.yaml $D/storylet-routes.yaml $D/knowledge.yaml; do git status --porcelain -- $f | grep -q . || { echo "WHY: $f not modified"; exit 1; }; done
grep -q "i_3c_evacuation" $D/incidents.yaml || { echo "WHY: incident missing"; exit 1; }
grep -q "evacuation_complete" $D/pacing.yaml || { echo "WHY: ending latch not changed"; exit 1; }
grep -q "SL-3C-H" $D/storylet-routes.yaml || { echo "WHY: recovery storylet missing"; exit 1; }
grep -q "variants" $D/pacing.yaml || { echo "WHY: ending variants missing"; exit 1; }
$PY -c "from pathlib import Path; from storygame.story_package.loader import load_story_package as l; p=l(Path('$D')); e=p.pacing.ending; print(e.when, len(e.variants))" || { echo "WHY: package does not load"; exit 1; }
[ -f tests/test_3c_finale_journey.py ] || { echo "WHY: journey test missing"; exit 1; }
$PY -m ruff format --check storygame tests || { echo "WHY: not ruff-formatted"; exit 1; }
SUITES=""; for t in test_3c_finale_journey test_story_ending test_3c_cue_chain test_incident_loader test_incident_engine test_incident_recovery test_incident_handoff_guard test_leak_terms test_markdown_story_package test_package_audit test_scene_roleplay_contract test_3a_records_followup test_disclosure_guards test_scene_relative_pacing test_spine_expected_reveals test_late_scene_repro test_knowledge_leakage_matrix test_narration_place_names test_speaker_presence test_surface_gates_scope test_medical_records_alias test_3ab_spine_prompts test_2c_paths_repro test_knowledge_projection test_loader_pacing_producers test_entry_variants; do [ -f tests/$t.py ] && SUITES="$SUITES tests/$t.py"; done
$PY -m pytest -q -p no:cacheprovider -x $SUITES || { echo "WHY: suites failed"; exit 1; }
echo ok
